# Correcciones de contenido del piloto (D-12) y lecturas nuevas. Se aplica sobre brujula.html.
import json,re,sys
B=sys.argv[1]
s=open(B).read()
log=[]
def rep(old,new,count=1):
    global s
    n=s.count(old)
    assert n==count,(old[:80],n)
    s=s.replace(old,new); log.append(old[:60])

def arr(stem,new):
    """sustituye el array completo que contiene ese enunciado"""
    global s
    i=s.find(json.dumps(stem,ensure_ascii=False))
    assert i>0,stem
    assert s.count(json.dumps(stem,ensure_ascii=False))==1,stem
    a=s.rfind('[',0,i); b=s.find('"]',i)+2
    s=s[:a]+json.dumps(new,ensure_ascii=False)+s[b:]; log.append("Q "+new[0]+" "+new[1][:40])

